CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"1c74696d-acb3-5dc1-8c13-bdd0ffc74ba9","source_id":"2800","name_en":"barbell sitted alternate leg raise (female)","name_ar":"\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u062c\u0644\u0648\u0633 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0639 \u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0628\u062f\u064a\u0644\u0629 (\u0623\u0646\u062b\u0649)","match_names":["barbell sitted alternate leg raise (female)"],"muscle":"core","equipment":"barbell","aliases":["barbell sitted alternate leg raise (female)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench with your back straight and hold a barbell across your thighs.\nPlace your hands on the sides of the bench for support.\nKeeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.\nLower the leg back down and repeat with the other leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0623\u0628\u0642\u0650 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0627\u0631\u0641\u0639 \u0625\u062d\u062f\u0649 \u0633\u0627\u0642\u064a\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646 \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636.\n\u062e\u0641\u0636 \u0627\u0644\u0633\u0627\u0642 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644 \u0648\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2800","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2800-BCs0G2F.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2800-BCs0G2F.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"88c6bbf0-25c8-536c-8dd5-ac14cf7d867c","source_id":"0100","name_en":"barbell skier","name_ar":"\u0645\u062a\u0632\u0644\u062c \u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell skier"],"muscle":"shoulders","equipment":"barbell","aliases":["barbell skier"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.\nBend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\nSimultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.\nAs you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643 \u0628\u064a\u0646\u0645\u0627 \u062a\u0642\u0641\u0632 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0639\u0646\u062f \u0648\u0635\u0648\u0644\u0643 \u0625\u0644\u0649 \u0642\u0645\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0642\u0645 \u0628\u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629 \u0628\u0633\u0631\u0639\u0629 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\