062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0645\u0631\u0641\u0648\u0639\u0629 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0628\u0631 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643\u060c \u0645\u0639 \u0648\u0636\u0639\u0647 \u0639\u0644\u0649 \u0627\u0644\u0641\u062e\u0627\u062e \u0623\u0648 \u0627\u0644\u062d\u0630\u0641 \u0627\u0644\u062e\u0644\u0641\u064a.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0628\u064a\u0646\u0645\u0627 \u062a\u0642\u0648\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u062e\u0644\u0641 \u0648\u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a.\n\u0627\u062e\u0641\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0645\u0646\u062e\u0641\u0636\u064b\u0627 \u0628\u0642\u062f\u0631 \u0645\u0627 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u0642\u0645 \u0628\u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0639\u0628\u0631 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0648\u0642\u0648\u0641 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0101","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0101-euI1BwR.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0101-euI1BwR.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e2e26a4e-73b2-5cda-8586-3a46d9a8f3b9","source_id":"2810","name_en":"barbell split squat v. 2","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0645\u0642\u0633\u0645 \u0628\u0627\u0644\u062d\u062f\u064a\u062f v.2","match_names":["barbell split squat v. 2"],"muscle":"quads","equipment":"barbell","aliases":["barbell split squat v. 2"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.\nTake a large step forward with your right foot, keeping your torso upright.\nLower your body by bending your knees and hips until your right thigh is parallel to the ground.\nPause for a moment, then push through your right heel to return to the starting position.\nRepeat with your left leg forward for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643.\n\u062e\u0630 \u062e\u0637\u0648\u0629 \u0643\u0628\u064a\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u062c\u0630\u0639 \u0641\u064a \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0628\u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0645\u0637\u0644\u0648\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2810","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2810-HBYyX94.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2810-HBYyX94.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"86ba1c2a-66f0-5a74-8099-faa0e239b637","source_id":"0102","name_en":"barbell squat (on knees)","name_ar":"\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u062d\u062f\u064a\u062f (\u0639\u0644\u0649 \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646)","match_names":["barbell squat (on knees)"],"muscle":"quads","equipment":"barbell","aliases":["barbell squat (on knees)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.\nPlace a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.\nEngage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.\nContinue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\nPause for a moment at the bottom, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0631\u0643\u0648\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0643\u062a\u0641\u064a\u0643\u060c \u0648\u0623\u0645\u0633\u0643\u0647 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0631\u0641\u0639 \u0635\u062f\u0631\u0643 \u0628\u064a\u0646\u0645\u0627 \u062a\u0642\u0648\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0627\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0625\u0644\u0649 \u0623\u062f\u0646\u0649 \u0645\u0633\u062a\u0648\u0649 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0102","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0102-oR7O9LW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0102-oR7O9LW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a5d71fed-22a8-560a-8a65-0a0b76ce9a5e","source_id":"2798","name_en":"barbell squat jump step rear lunge","name_ar":"\u0642\u0641\u0632\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u062e\u0637\u0648\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639 \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["barbell squat jump step rear lunge"],"muscle":"quads","equipment":"barbell","aliases":["barbell squat jump step rear lunge"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.\nLower your body into a squat position by bending your knees and pushing your hips back.\nExplode upwards, jumping off the ground as high as you can.\nLand softly on your feet and immediately step back with one leg into a reverse lunge.\nLower your body down until your front thigh is parallel to the ground, keeping your back straight.\nPush through your front heel to return to the starting position.\nRepeat the jump and lunge sequence on the other leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u0646\u0641\u062c\u0631 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0627\u0642\u0641\u0632 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646.\n\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0642\u062f\u0645\u064a\u0643 \u062b\u0645 \u062a\u0631\u0627\u062c\u0639 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0627\u0646\u062f\u0641\u0627\u0639 \u0639\u0643\u0633\u064a.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0642\u0641\u0632\u0629 \u0648\u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2798","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2798-RYcV1kH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2798-RYcV1kH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"512acc99-cd44-5a68-8dea-f49b481420a9","source_id":"0103","name_en":"barbell standing ab rollerout","name_ar":"\u064a\u0642\u0641 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0623\u0633\u0627\u0633 \u0631\u0648\u0644\u0648\u062a","match_names":["barbell standing ab rollerout"],"muscle":"core","equipment":"barbell","aliases":["barbell standing ab rollerout"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.\nEngage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.\nContinue rolling the barbell forward until your body is fully extended and your hands are directly above your head.\nPause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643 \u0648\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062f\u062d\u0631\u062c\u0629 \u0627\u0644\u062d\u062f\u064a\u062f \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0633\u0645\u0643 \u0645\u0645\u062a\u062f\u064b\u0627 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u064a\u062f\u064a\u0643 \u0641\u0648\u0642 \u0