set","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1372","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1372-8ozhUIZ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1372-8ozhUIZ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1d72049c-9f37-5f9c-8067-fd35cec01ffe","source_id":"0106","name_en":"barbell standing close grip curl","name_ar":"\u0627\u0644\u062d\u062f\u064a\u062f \u0648\u0627\u0642\u0641\u064b\u0627 \u0628\u0642\u0628\u0636\u0629 \u0642\u0631\u064a\u0628\u0629","match_names":["barbell standing close grip curl"],"muscle":"biceps","equipment":"barbell","aliases":["barbell standing close grip curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.\nKeep your elbows close to your torso and your upper arms stationary throughout the movement.\nExhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale as you slowly begin to bring the barbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0630\u0639\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u062a\u062c\u0639\u064a\u062f \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646. \u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u0628\u0627\u0631 \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0646\u0634\u0642 \u0628\u064a\u0646\u0645\u0627 \u062a\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0106","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0106-4dUn2iv.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0106-4dUn2iv.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d43a7709-2e2d-564c-8263-597bfa742a57","source_id":"1456","name_en":"barbell standing close grip military press","name_ar":"\u064a\u0642\u0641 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0627\u0644\u0639\u0633\u0643\u0631\u064a\u0629","match_names":["barbell standing close grip military press"],"muscle":"shoulders","equipment":"barbell","aliases":["barbell standing close grip military press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.\nLift the barbell to shoulder height, keeping your elbows close to your body.\nPress the barbell overhead, extending your arms fully.\nLower the barbell back to shoulder height.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u064a\u062f\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u0639\u0644\u0648\u064a\u060c \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1456","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1456-wdRZISl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1456-wdRZISl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4e929604-e697-5430-8431-eefc187b290c","source_id":"2414","name_en":"barbell standing concentration curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u062f\u0627\u0626\u0645\u0629 \u0628\u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell standing concentration curl"],"muscle":"biceps","equipment":"barbell","aliases":["barbell standing concentration curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.\nRest your opposite hand on your thigh for support.\nKeeping your upper arm stationary, exhale and curl the weight up towards your shoulder.\nPause for a moment at the top, squeezing your biceps.\nInhale and slowly lower the weight back down to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u0645\u0639\u0627\u0643\u0633\u0629 \u0639\u0644\u0649 \u0641\u062e\u0630\u0643 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0648\u0632\u0646 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0648\u0632\u0646 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2414","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2414-vsMcDi9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4