064a\u0629\u060c \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0623\u0645\u0627\u0645 \u0627\u0644\u0628\u0627\u0631 \u0642\u0644\u064a\u0644\u064b\u0627.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u0639\u0644\u0648\u064a\u060c \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1457","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1457-Kyd9Rz5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1457-Kyd9Rz5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"03694c44-b577-5c4b-8474-01fe0a6526fa","source_id":"0113","name_en":"barbell standing wide-grip curl","name_ar":"\u064a\u0642\u0641 \u0627\u0644\u062d\u062f\u064a\u062f \u062d\u0644\u064a\u0642\u0629 \u0628\u0642\u0628\u0636\u0629 \u0648\u0627\u0633\u0639\u0629","match_names":["barbell standing wide-grip curl"],"muscle":"biceps","equipment":"barbell","aliases":["barbell standing wide-grip curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.\nLet the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.\nKeeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.\nContinue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the barbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062f\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u064a\u062a\u062f\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0630\u0631\u0627\u0639 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0634\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0113","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0113-NdIb5Z1.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0113-NdIb5Z1.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2e3850b5-11d3-5fc9-8e93-86bc4af9f5a0","source_id":"0114","name_en":"barbell step-up","name_ar":"\u062e\u0637\u0648\u0629 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0628\u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell step-up"],"muscle":"glutes","equipment":"barbell","aliases":["barbell step-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand in front of a bench or step with a barbell resting on your upper back.\nPlace one foot on the bench or step, ensuring your entire foot is in contact with the surface.\nPush through your heel and step up onto the bench or step, fully extending your hip and knee.\nPause briefly at the top, then lower yourself back down to the starting position.\nRepeat with the opposite leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0623\u0645\u0627\u0645 \u0645\u0642\u0639\u062f \u0623\u0648 \u062e\u0637\u0648\u0629 \u0645\u0639 \u0648\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643.\n\u0636\u0639 \u0642\u062f\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u062f\u0631\u062c\u0629\u060c \u0648\u062a\u0623\u0643\u062f \u0645\u0646 \u0645\u0644\u0627\u0645\u0633\u0629 \u0642\u062f\u0645\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0644\u0633\u0637\u062d.\n\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0648\u0627\u0635\u0639\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u062e\u0637\u0648\u0629\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643 \u0648\u0627\u0644\u0631\u0643\u0628\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0641\u062a\u0631\u0629 \u0648\u062c\u064a\u0632\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u0646\u0632\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0645\u0639\u0627\u0643\u0633\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0114","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0114-Kxquu2E.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0114-Kxquu2E.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"85c13343-4c39-5219-8f88-b9ecdd6f8754","source_id":"0115","name_en":"barbell stiff leg good morning","name_ar":"\u0633\u0627\u0642 \u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u0627\u0633\u064a\u0629 \u0635\u0628\u0627\u062d \u0627\u0644\u062e\u064a\u0631","match_names":["barbell stiff leg good morning"],"muscle":"glutes","equipment":"barbell","aliases":["barbell stiff leg good morning"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your knees slightly bent.\nHold the barbell across your upper back, resting it on your traps.\nKeeping your back straight, hinge forward at the hips, pushing your glutes back.\nLower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.\nEngage your glutes and hamstrings to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643\u060c \u062b\u0645 \u0636\u0639\u0647 \u0639\u0644\u0649 \u0623\u0641\u062e\u0627\u062e\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643\u060c \u062b\u0645 \u0642\u0645 \u0628\u0627\u0644\u0645\u0641\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u0627\u062f\u0641\u0639 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u062e\u0641\u0636 \u062c\u0630\u0639\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0115","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0115-JrOHAZc.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0115-JrOHAZc.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1c32ece8-22f8-50dd-8272-69b1f05fffad","source_id":"0116","name_en":"barbell straight leg deadlift","name_ar":"\u0627\u0644\u0631\u0641\u0639\u0629 \u0627\u0644\u0645\u0645\u064a\u062a\u0629 \u0628\u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u0629","match_names":["barbell straight leg deadlift"],"muscle":"hamstrings","equipment":"barbell","aliases":["barbell straight leg deadlift"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your toes pointing forward.\nHold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\nBend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.\nLower the barbell until you feel a stretch in your hamstrings.\nEngage your hamstrings and glutes to lift the barbell back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0649 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u0628\u0627\u0631 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u0627\u0641 \u0644\u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0116","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0116-hrVQWvE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0116-hrVQWvE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"abded1af-66f3-5a61-85c6-2ac1187ec641","source_id":"0117","name_en":"barbell sumo deadlift","name_ar":"\u0627\u0644\u0631\u0641\u0639\u0629 \u0627\u0644\u0645\u0645\u064a\u062a\u0629 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u0633\u0648\u0645\u0648","match_names":["barbell sumo deadlift"],"muscle":"glutes","equipment":"barbell","aliases":["barbell sumo deadlift"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet wider than shoulder-width apart, toes pointing outwards.\nPlace a barbell on the ground in front of you, centered between your feet.\nBend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.\nEngage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.\nAs you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.\nPause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u0646\u062d\u0648 \u0627\u0644\u062e\u0627\u0631\u062c.\n\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u062a\u0645\u0631\u0643\u0632\u064b\u0627 \u0628\u064a\u0646 \u0642\u062f\u0645\u064a\u0643.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649\u060c \u0644\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u064a\u0643 \u0644\u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0631\u0641\u0639\u060c \u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627\u060c \u0648\u0627\u062f\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u0644\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0117","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0117-KgI0tqW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0117-KgI0tqW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"50fd81c4-ee9d-5960-8e88-d03df3b60833","source_id":"3305","name_en":"barbell thruster","name_ar":"\u0627\u0644\u062f\u0627\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f","match_names":["barbell thruster"],"muscle":"shoulders","equipment":"barbell","aliases":["barbell thruster"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.\nLower into a squat position by bending your knees and pushing your hips back.\nAs you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.\nLower the barbell back to shoulder height as you lower back into the squat position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0627\u0646\u0632\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0642\u0645 \u0628\u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0639\u0628\u0631 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0648\u0642\u0648\u0641\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0639\u0644\u0649 \u0627\u0644\u062d\u062f\u064a\u062f \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0628\u064a\u0646\u0645\u0627 \u062a\u0646\u0632\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3305","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["quadriceps","glutes","hamstrings","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-da