u0629\u060c \u0648\u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0645\u062a\u062c\u0647\u062a\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u064a\u062f\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u0627\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u0633\u0645\u0627\u062d \u0644\u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0627\u0644\u062a\u062f\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0639\u0635\u0645\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u062c\u0644\u0628 \u0627\u0644\u062d\u062f\u064a\u062f \u0646\u062d\u0648 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0125","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","brachialis"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0125-6kSxYnw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0125-6kSxYnw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bef6644e-a3d2-5f03-8e25-6f68452b8b50","source_id":"0127","name_en":"barbell zercher squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u062d\u062f\u064a\u062f zercher","match_names":["barbell zercher squat"],"muscle":"glutes","equipment":"barbell","aliases":["barbell zercher squat"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and toes slightly turned out.\nHold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.\nEngage your core and keep your chest lifted as you lower your hips back and down into a squat position.\nKeep your knees in line with your toes and your weight in your heels.\nPause for a moment at the bottom of the squat, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0625\u062e\u0631\u0627\u062c \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0641\u064a \u0627\u0646\u062d\u0646\u0627\u0621\u0627\u062a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u0642\u0636\u064a\u0628 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0631\u0641\u0639 \u0635\u062f\u0631\u0643 \u0623\u062b\u0646\u0627\u0621 \u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u062e\u0644\u0641 \u0648\u0644\u0644\u0623\u0633\u0641\u0644 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u062a\u0645\u0627\u0634\u064a\u0629 \u0645\u0639 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0648\u0648\u0632\u0646\u0643 \u0639\u0644\u0649 \u0643\u0639\u0628\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0127","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0127-LSTChY9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0127-LSTChY9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"20bdbc5c-c88c-5cde-832f-501882b9971f","source_id":"3212","name_en":"basic toe touch (male)","name_ar":"\u0644\u0645\u0633\u0629 \u0625\u0635\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 (\u0630\u0643\u0631)","match_names":["basic toe touch (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["basic toe touch (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your arms by your sides.\nBend forward at the waist, keeping your back straight and your knees slightly bent.\nReach down towards your toes with your hands, keeping your legs as straight as possible.\nPause for a moment at the bottom, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u062e\u0635\u0631\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3212","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3212-BbfB8Gb.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3212-BbfB8Gb.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6a5c163f-ed5a-598f-82a8-6db2c9faad9a","source_id":"0128","name_en":"battling ropes","name_ar":"\u062d\u0628\u0627\u0644 \u0627\u0644\u0642\u062a\u0627\u0644","match_names":["battling ropes"],"muscle":"shoulders","equipment":"rope","aliases":["battling ropes"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and knees slightly bent.\nHold one end of the rope in each hand, with your palms facing each other.\nRaise your arms to shoulder height, keeping your elbows slightly bent.\nBegin making alternating waves with the ropes by rapidly raising and lowering each arm.\nContinue for the desired duration or number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0623\u062d\u062f \u0637\u0631\u0641\u064a \u0627\u0644\u062d\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0631\u0641\u0639\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u0628\u062f\u0623 \u0628\u0639\u0645\u0644 \u0645\u0648\u062c\u0627\u062a \u0645\u062a\u0646\u0627\u0648\u0628\u0629 \u0628\u0627\u0644\u062d\u0628\u0627\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0631\u0641\u0639 \u0648\u062e\u0641\u0636 \u0643\u0644 \u0630\u0631\u0627\u0639 \u0628\u0633\u0631\u0639\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0623\u0648 \u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0128","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["forearms","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0128-RJa4tCo.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0128-RJa4tCo.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bb001fa2-ed0b-55c9-843d-0f9530674cbc","source_id":"3360","name_en":"bear crawl","name_ar":"\u0632\u062d\u0641 \u0627\u0644\u062f\u0628","match_names":["bear crawl"],"muscle":"cardio","equipment":"bodyweight","aliases":["bear crawl"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Start on all fours with your hands directly under your shoulders and your knees directly under your hips.\nLift your knees slightly off the ground, keeping your back flat and your core engaged.\nMove your right hand and left foot forward simultaneously, followed by your left hand and right foot.\nContinue crawling forward, alternating your hand and foot movements.\nMaintain a steady pace and keep your core tight throughout the exercise.\nContinue for the desired distance or time.","steps_ar":"\u0627\u0628\u062f\u0623 \u0639\u0644\u0649 \u0623\u0631\u0628\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u064a\u0643 \u0648\u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0627\u0644\u0648\u0631\u0643\u064a\u0646.\n\u0627\u0631\u0641\u0639\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0638\u0647\u0631\u0643 \u0645\u0633\u0637\u062d\u064b\u0627 \u0648\u062c\u0630\u0639\u0643 \u0645\u0646\u0634\u063a\u0644\u064b\u0627.\n\u062d\u0631\u0643 \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a\u060c \u0645\u062a\u0628\u0648\u0639\u064b\u0627 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0632\u062d\u0641 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u062d\u0631\u0643\u0627\u062a \u064a\u062f\u0643 \u0648\u0642\u062f\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u062a\u064a\u0631\u0629 \u062b\u0627\u0628\u062a\u0629 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0634\u062f \u062c\u0633\u0645\u0643 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0623\u0648 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3360","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["core","shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3360-0Yz8WdV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3360-0Yz8WdV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"64ecb368-3713-55b4-8e51-7041bb6459ae","source_id":"1259","name_en":"behind head chest stretch","name_ar":"\u062e\u0644\u0641 \u0627\u0644\u0631\u0623\u0633 \u062a\u0645\u062a\u062f \u0627\u0644\u0635\u062f\u0631","match_names":["behind head chest stretch"],"muscle":"chest","equipment":"assisted","aliases":["behind head chest stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand tall with your feet shoulder-width apart.\nInterlace your fingers behind your head with your elbows pointing outwards.\nSlowly squeeze your shoulder blades together and push your chest forward.\nHold the stretch for 15-30 seconds.\nRelease the stretch and repeat as desired.","steps_ar":"\u0642\u0641 \u0637\u0648\u064a\u0644\u064b\u0627 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0634\u0628\u0643 \u0623\u0635\u0627\u0628\u0639\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0627\u0636\u063a\u0637 \u0628\u0628\u0637\u0621 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0648\u0627\u062f\u0641\u0639 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0648\u0643\u0631\u0631 \u062d\u0633\u0628 \u0627\u0644\u0631\u063a\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1259","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1259-QoHIhPl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1259-QoHIhPl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e0d5907c-d928-5598-801f-51fc5f9f02be","source_id":"0129","name_en":"bench dip (knees bent)","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 (\u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646)","match_names":["bench dip (knees bent)"],"muscle":"triceps","equipment":"bodyweight","aliases":["bench dip (knees bent)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.\nSlide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.\nBend your elbows and lower your body towards the ground, keeping your back close to the bench.\nPause for a moment at the bottom, then push yourself back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u0643\u0631\u0633\u064a \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629 \u0628\u062c\u0648\u0627\u0631 \u0648\u0631\u0643\u064a\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0645\u0624\u062e\u0631\u062a\u0643 \u0639\u0646 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0627\u0641\u0631\u062f\u064a \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0638\u0647\u0631\u0643 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0129","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0129-RrLske5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0129-RrLske5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f613de86-ae4f-5f96-84ca-cc5be9a6a476","source_id":"1399","name_en":"bench dip on floor","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636","match_names":["bench dip on floor"],"muscle":"triceps","equipment":"bodyweight","aliases":["bench dip on floor"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.\nSlide your butt off the bench, supporting your weight with your hands.\nLower your body by bending your elbows until your upper arms are parallel to the floor.\nPush yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u0643\u0631\u0633\u064a \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0631\u0643 \u0645\u0624\u062e\u0631\u062a\u0643 \u0645\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0648\u0627\u062f\u0639\u0645 \u0648\u0632\u0646\u0643 \u0628\u064a\u062f\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1399","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1399-9RT8oQW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1399-9RT8oQW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"117c4d4a-4795-528d-8081-53b49c24c3f3","source_id":"0130","name_en":"bench hip extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621","match_names":["bench hip extension"],"muscle":"glutes","equipment":"bodyweight","aliases":["bench hip extension"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on a bench with your back against the bench and your feet flat on the ground.\nPlace your hands on the bench for support.\nEngage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.\nPause for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0645\u0642\u0639\u062f \u062d\u062a\u0649 \u064a\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0130","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0130-u27Kcdz.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0130-u27Kcdz.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"be001e48-085c-5308-81e3-b95b16b21b9f","source_id":"3019","name_en":"bench pull-ups","name_ar":"\u0639\u0645\u0644\u064a\u0627\u062a \u0633\u062d\u0628 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621","match_names":["bench pull-ups"],"muscle":"back","equipment":"bodyweight","aliases":["bench pull-ups"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Position yourself under a bar or a sturdy horizontal surface that is at chest height.\nGrab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.\nHang with your arms fully extended and your body straight.\nPull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.\nContinue pulling until your chin is above the bar or surface.\nLower yourself back down to the starting position with control.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0646\u0641\u0633\u0643 \u062a\u062d\u062a \u0634\u0631\u064a\u0637 \u0623\u0648 \u0633\u0637\u062d \u0623\u0641\u0642\u064a \u0642\u0648\u064a \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0628\u0627\u0631 \u0623\u0648 \u0627\u0644\u0633\u0637\u062d \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u0633\u062d\u0628 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631 \u0623\u0648 \u0627\u0644\u0633\u0637\u062d \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0648\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0641\u0648\u0642 \u0627\u0644\u0634\u0631\u064a\u0637 \u0623\u0648 \u0627\u0644\u0633\u0637\u062d.\n\u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0639 \u0627\u0644\u062a\u062d\u0643\u0645.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3019","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3019-mExgrF9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3019-mExgrF9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6aadbacc-c259-5b87-84f9-e50dba17fc0e","source_id":"3639","name_en":"bent knee lying twist (male)","name_ar":"\u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u0629 \u0645\u0644\u062a\u0648\u064a\u0629 (\u0630\u0643\u0631)","match_names":["bent knee lying twist (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["bent knee lying twist (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nExtend your arms out to the sides, perpendicular to your body.\nKeeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.\nPause for a moment, then engage your core and slowly lift your knees back to the starting position.\nRepeat the movement to the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u062c\u0633\u0645\u0643.\n\u0623\u0628\u0642\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u0639\u064b\u0627\u060c \u0648\u0642\u0645 \u0628\u062e\u0641\u0636\u0647\u0645\u0627 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0628\u0647\u062f\u0641 \u0644\u0645\u0633 \u0627\u0644\u0623\u0631\u0636 \u0628\u0631\u0643\u0628\u062a\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u062c\u0630\u0639\u0643 \u0648\u0627\u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3639","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["obliques","hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3639-6sYyrRX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3639-6sYyrRX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"705ade68-b5f6-5db2-8dad-7909cbec65bd","source_id":"1770","name_en":"biceps leg concentration curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0633\u0627\u0642 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646","match_names":["biceps leg concentration curl"],"muscle":"biceps","equipment":"bodyweight","aliases":["biceps leg concentration curl"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on a bench with your legs spread apart and your feet flat on the ground.\nHold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.\nWith your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.\nSqueeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0633\u0627\u0642\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629\u060c \u062b\u0645 \u0636\u0639 \u0645\u0631\u0641\u0642\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0645\u0646 \u0641\u062e\u0630\u0643\u060c \u0641\u0648\u0642 \u0627\u0644\u0631\u0643\u0628\u0629 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1770","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1770-sJFIDIp.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1770-sJFIDIp.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b1a44274-1b19-52c4-8a81-8442ff1844f9","source_id":"0139","name_en":"biceps narrow pull-ups","name_ar":"\u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0633\u062d\u0628 \u0627\u0644\u0636\u064a\u0642\u0629","match_names":["biceps narrow pull-ups"],"muscle":"biceps","equipment":"bodyweight","aliases":["biceps narrow pull-ups"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.\nEngage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.\nPause for a moment at the top, then slowly lower yourself back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0646\u062d\u0648\u0643 \u0648\u064a\u062f\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u0627\u0646 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643 \u0648\u0627\u0633\u062d\u0628 \u0646\u0641\u0633\u0643 \u0646\u062d\u0648 \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0639\u0644\u0649 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0139","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0139-50BETrz.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0139-50BETrz.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b2bd99a8-82c2-5b0d-8315-e856032826a2","source_id":"0140","name_en":"biceps pull-up","name_ar":"\u0633\u062d\u0628 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646","match_names":["biceps pull-up"],"muscle":"biceps","equipment":"bodyweight","aliases":["biceps pull-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.\nEngage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.\nPause at the top of the movement, then slowly lower yourself back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643 \u0648\u064a\u062f\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0633\u062d\u0628 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062c\u0644\u0628 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0140","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0140-guT8YnS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0140-guT8YnS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c79d5ac6-16c5-5a2f-818a-d527d454f95f","source_id":"0137","name_en":"body-up","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u062c\u0633\u0645","match_names":["body-up"],"muscle":"triceps","equipment":"bodyweight","aliases":["body-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.\nExtend your legs out in front of you, keeping your heels on the ground and your body straight.\nLower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.\nPause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0633\u0637\u062d \u0645\u0631\u062a\u0641\u0639\u060c \u0645\u062b\u0644 \u0645\u0642\u0639\u062f \u0623\u0648 \u0642\u0636\u0628\u0627\u0646 \u0645\u062a\u0648\u0627\u0632\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627\u064b.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643\u060c \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0644\u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0137","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0137-U6G2gk9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0137-U6G2gk9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
